        banter: [{ b: "elnea", title: "三本目", where: ["any"], lines: [["b", "先生、最近、肝の三本目の話、しないっすね"], ["a", "あら、してまへんか"], ["b", "してないっす。石の話、ちゃんと聞いてくれるっす。……ちょっと寂しいっす"], ["a", "ほな、今夜は肝の話をしまひょ。三本目どす"], ["b", "それっす"]] }],
        heal: true,
