        banter: [{ b: "barnabe", title: "要らんようになったら", lines: [["b", "先生、最近、おれの骨の話、しねえなあ"], ["a", "弟子に帳面を渡しましたさかい。骨の頁も、あの子のとこどす"], ["b", "……じゃあ、おれの骨、その弟子が欲しがるのか？"], ["a", "あの子は、肝のほうが好きどす"], ["b", "やめろよお"]] }],
